async function readForm(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 1024 * 1024) {
      const error = new Error('Request too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

function sendHtml(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(body);
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    if (request.method === 'GET' && url.pathname === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      return response.end(JSON.stringify({ status: 'ok' }));
    }
    if (request.method === 'GET' && url.pathname === '/') {
      return sendHtml(response, 200, projectsPage('', '', projectFilter(url.searchParams.get('filter')), readSearch(url.searchParams, 'projectSearch')));
    }
    if (request.method === 'POST' && url.pathname === '/projects') {
      const form = await readForm(request);
      const enteredName = form.get('name') || '';
      const name = enteredName.trim();
      if (!name) return sendHtml(response, 200, projectsPage('Project name is required', enteredName, projectFilter(form.get('filter')), readSearch(form, 'projectSearch')));
      createProject.run(name);
      response.writeHead(303, { Location: projectsLocation(projectFilter(form.get('filter')), readSearch(form, 'projectSearch')) });
      return response.end();
    }
    const rangeMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/due-range$/);
    if (request.method === 'POST' && rangeMatch) {
      const project = getProject.get(rangeMatch[1]);
      if (!project) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      const form = await readForm(request);
      const range = { from: (form.get('dueFrom') || '').trim(), through: (form.get('dueThrough') || '').trim(), search: readSearch(form, 'taskSearch') };
      let error = '';
      if ((range.from && !validDueDate(range.from)) || (range.through && !validDueDate(range.through))) {
        error = 'Due range must use valid YYYY-MM-DD dates';
      } else if (range.from && range.through && range.from > range.through) {
        error = 'Due from must not be after Due through';
      }
      const filter = taskFilter(form.get('filter'));
      const priority = priorityFilter(form.get('priorityFilter'));
      if (error) return sendHtml(response, 200, projectPage(project, filter, '', '', '', '', null, priority, null, readRange(form), error, range));
      response.writeHead(303, { Location: projectLocation(project.id, filter, priority, range) });
      return response.end();
    }
    const renameMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/rename$/);
    if (request.method === 'POST' && renameMatch) {
      const project = getProject.get(renameMatch[1]);
      if (!project) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to rename it.</p>'));
      const form = await readForm(request);
      const enteredName = form.get('name') || '';
      const name = enteredName.trim();
      const filter = taskFilter(form.get('filter'));
      if (!name) return sendHtml(response, 200, projectPage(project, filter, '', '', 'Project name is required', enteredName, null, priorityFilter(form.get('priorityFilter')), null, readRange(form)));
      renameProject.run(name, project.id);
      response.writeHead(303, { Location: projectLocation(project.id, filter, priorityFilter(form.get('priorityFilter')), readRange(form)) });
      return response.end();
    }
    const archiveMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/(archive|restore)$/);
    if (request.method === 'POST' && archiveMatch) {
      if (!getProject.get(archiveMatch[1])) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      const form = await readForm(request);
      setArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, archiveMatch[1]);
      response.writeHead(303, { Location: projectsLocation(archiveMatch[2] === 'archive' ? 'Active' : 'Archived', readSearch(form, 'projectSearch')) });
      return response.end();
    }
    const defaultPriorityMatch = url.pathname.match(/^\/projects\/([1-9]\d*)\/default-priority$/);
    if (request.method === 'POST' && defaultPriorityMatch) {
      const project = getProject.get(defaultPriorityMatch[1]);
      if (!project) return sendHtml(response, 404, page('Not found', '<h1>Not found</h1>'));
      if (project.archived) return sendHtml(response, 403, page('Archived project', '<h1>Archived project</h1><p>Restore the project to change its default.</p>'));
